            g.Field(x => x.F11Choice, f => f.DisplayName("Choice 4.11").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo"));
            g.Field(x => x.F12Tags, f => f.DisplayName("Tags 4.12").AllowedElementValue<string>("red", "red", "Red").AllowedElementValue<string>("green", "green", "Green").AllowedElementValue<string>("blue", "blue", "Blue").AllowedElementValue<string>("amber", "amber", "Amber"));
            g.Field(x => x.F13Code, f => f.DisplayName("Code 4.13").Pattern("[A-Z]{3}-[0-9]{3}"));
            g.Field(x => x.F14Percent, f => f.DisplayName("Percent 4.14").Range(0m, 100m));
            g.Field(x => x.F15Note, f => f.DisplayName("Note 4.15").MaxLength(500).Annotate("ui:control", "textarea"));
            g.Field(x => x.F16Text, f => f.DisplayName("Text 4.16").MaxLength(80).Validation(p => p.For<LargeFormSubmitProfile>(r => r.Required())));
            g.Field(x => x.F17Count, f => f.DisplayName("Count 4.17").Range(0, 10000));
            g.Field(x => x.F18Amount, f => f.DisplayName("Amount 4.18").Min(0m));
            g.Field(x => x.F19Flag, f => f.DisplayName("Flag 4.19").Default(false));
            g.Field(x => x.F20Date, f => f.DisplayName("Date 4.20").Max(new DateOnly(2099, 12, 31)));
            g.Field(x => x.F21Choice, f => f.DisplayName("Choice 4.21").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo"));
            g.Field(x => x.F22Tags, f => f.DisplayName("Tags 4.22").AllowedElementValue<string>("red", "red", "Red").AllowedElementValue<string>("green", "green", "Green").AllowedElementValue<string>("blue", "blue", "Blue").AllowedElementValue<string>("amber", "amber", "Amber"));
            g.Field(x => x.F23Code, f => f.DisplayName("Code 4.23").Pattern("[A-Z]{3}-[0-9]{3}").Validation(p => p.For<LargeFormSubmitProfile>(r => r.Required())));
            g.Field(x => x.F24Percent, f => f.DisplayName("Percent 4.24").Range(0m, 100m));
            g.Field(x => x.F25Note, f => f.DisplayName("Note 4.25").MaxLength(500).Annotate("ui:control", "textarea"));
        }, o => o.DisplayName("Section 4").Resettable());
        builder.Collection(x => x.Lines, lines =>
        {
            lines.DisplayName("Lines");
            lines.Item<LargeForm100Line>("LINE", line =>
            {
                line.Field(x => x.Description, f => f.DisplayName("Description").MaxLength(200).Annotate("ui:title", true));
                line.Field(x => x.Quantity, f => f.DisplayName("Quantity").Range(0, 100000).Default(1));
                line.Field(x => x.UnitPrice, f => f.DisplayName("Unit Price").Min(0m));
                line.Field(x => x.Amount, f => f.DisplayName("Amount").Min(0m));
                line.Field(x => x.Category, f => f.DisplayName("Category").AllowedValue("goods", "goods", "Goods").AllowedValue("services", "services", "Services").AllowedValue("fees", "fees", "Fees"));
                line.Field(x => x.Taxable, f => f.DisplayName("Taxable").Default(true));
                line.Field(x => x.ServiceDate, f => f.DisplayName("Service Date"));
                line.Field(x => x.Reference, f => f.DisplayName("Reference").Pattern("[A-Z]{3}-[0-9]{3}"));
                line.Field(x => x.DiscountPercent, f => f.DisplayName("Discount %").Range(0m, 100m));
                line.Field(x => x.Notes, f => f.DisplayName("Notes").MaxLength(500).Annotate("ui:control", "textarea"));
            });
            lines.MaxCount(1000);
            lines.AggregateSum("Amount").LessThanOrEqual(1_000_000_000m);
        });
        builder.NestedNode(x => x.Party, party => party
            .DisplayName("Party")
            .Bind<LargeForm100Person>("PERSON", p => { p.Field(x => x.FullName, f => f.DisplayName("Full Name")); p.Field(x => x.BirthDate, f => f.DisplayName("Birth Date")); })
            .Bind<LargeForm100Organization>("ORGANIZATION", o => { o.Field(x => x.LegalName, f => f.DisplayName("Legal Name")); o.Field(x => x.TaxId, f => f.DisplayName("Tax Id").Pattern("[A-Z]{2}[0-9]{8}")); })
            .DefaultType<LargeForm100Organization>());
        builder.Operation("SUBMIT", x => x.Submit);
        builder.OnChange(path => path.Collection(x => x.Lines).Field(x => x.Amount), x => x.RecalculateLines);
        builder.OnChange(path => path.Collection(x => x.Lines).Any(), x => x.RecalculateLines);
        return builder.Build();
    }
}
